INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (1, 2, "リリ", 1, 1, 321, 24001, 0, 40011, "もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n", 125801);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (2, 2, "クリア", 1, 1, 322, 24001, 0, 40011, "初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます", 126001);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (3, 2, "プレシア", 1, 1, 323, 24001, 0, 40011, "んーと。\nこれ、あげる。\nはい", 126101);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (4, 2, "リリ", 2, 1, 324, 24001, 0, 40011, "あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します", 125801);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (5, 2, "クリア", 2, 1, 325, 24001, 0, 40011, "こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです", 126001);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (6, 2, "プレシア", 2, 1, 326, 24001, 0, 40011, "お兄。\nきてくれて、うれしい", 126101);
